<?php
declare(strict_types=1);
namespace DigiForge\POD;
use WP_Error;
/** Cookie-authenticated local customer drafts; production remains operator-gated. */
final class CustomerEditorWorkflow
{
 public function register():void {
  add_shortcode('digiforge_personalization_editor',[$this,'shortcode']);
  add_action('rest_api_init',function():void {
   register_rest_route('digiforge/v1','/customer-editor/access',['methods'=>'POST','permission_callback'=>fn($r)=>$this->permission($r,true),'callback'=>fn($r)=>$this->dispatch($r,'grant')]);
   register_rest_route('digiforge/v1','/customer-editor/mockup-evidence',['methods'=>'POST','permission_callback'=>fn($r)=>$this->permission($r,true),'callback'=>fn($r)=>$this->dispatch($r,'mockup')]);
   foreach(['asset'=>'mockupAsset','intake'=>'mockupIntake','review'=>'mockupReview','bind'=>'mockupBind']as $route=>$action)register_rest_route('digiforge/v1','/pod/product-mockup/'.$route,['methods'=>'POST','permission_callback'=>fn($r)=>$this->permission($r,true),'callback'=>fn($r)=>$this->dispatch($r,$action)]);
   foreach(['view'=>'GET','upload'=>'POST','fields'=>'POST','approve'=>'POST','revoke'=>'POST','intake'=>'POST','publish'=>'POST']as $action=>$verb)register_rest_route('digiforge/v1','/customer-editor/(?P<session>[A-Za-z0-9_-]{1,80})/'.$action,['methods'=>$verb,'permission_callback'=>fn($r)=>$this->permission($r,in_array($action,['revoke','intake','publish'],true)),'callback'=>fn($r)=>$this->dispatch($r,$action)]);
  });
 }
 private function permission(\WP_REST_Request $r,bool $operator):bool|WP_Error {
  if(get_current_user_id()<1||!current_user_can($operator?'manage_digiforge_pod':'read'))return new WP_Error('customer_editor_auth_required','Sign in with the authorized account.',['status'=>403]);
  if(!wp_verify_nonce($r->get_header('X-WP-Nonce'),'wp_rest'))return new WP_Error('customer_editor_nonce_required','Refresh this page before continuing.',['status'=>403]);return true;
 }
 public function dispatch(\WP_REST_Request $r,string $action):\WP_REST_Response|WP_Error {
  $allowed=$this->permission($r,in_array($action,['grant','mockup','revoke','intake','publish','mockupAsset','mockupIntake','mockupReview','mockupBind'],true));if($allowed instanceof WP_Error)return $allowed;
  if(strlen((string)$r->get_body())>(in_array($action,['upload','mockupAsset'],true)?8388608:65536))return new WP_Error('customer_editor_request_limit','The request exceeds the local limit.',['status'=>413]);
  $repo=new CustomerEditorRepository();$key=(string)$r->get_param('session');
  try{if($action==='view')$result=$repo->view($key);else{$p=$r->get_json_params();if(!is_array($p))throw new \InvalidArgumentException();$keys=match($action){'mockupAsset'=>['image_base64','sha256'],'mockupIntake'=>['reference','sha256','reference_render_id','parent_sha256'],'mockupReview'=>['recipe_sha256','outcome','flags','notes'],'mockupBind'=>['render_id','recipe_key','recipe_version','recipe_sha256'],'fields'=>array_key_exists('submit_for_review',$p)?['expected_head','submit_for_review','expected_selection_revision']:(array_key_exists('image_order',$p)?['expected_head','image_order']:['expected_head','fields']),'approve'=>['version_sha256','context_sha256'],'revoke'=>['access_sha256'],'intake'=>isset($p['operation'])?($p['operation']==='PHOTO_VIEW'?['operation','shop_key']:['operation','shop_key','selection_sha256','expected_revision','decision','note']):['version_sha256','image_field','rights','cutout_key'],'mockup'=>['reference','sha256'],default=>null};if($keys!==null&&(count($p)!==count($keys)||array_diff(array_keys($p),$keys)))throw new \InvalidArgumentException();$result=match($action){'mockupAsset'=>(new ProductMockupRegistry())->registerAsset($p['image_base64'],$p['sha256']),'mockupIntake'=>(new ProductMockupRegistry())->intake($p['reference'],$p['sha256'],$p['reference_render_id'],$p['parent_sha256']),'mockupReview'=>(new ProductMockupRegistry())->review($p['recipe_sha256'],$p['outcome'],$p['flags'],$p['notes']),'mockupBind'=>(new ProductMockupRegistry())->bind($p['render_id'],$p['recipe_key'],$p['recipe_version'],$p['recipe_sha256']),'grant'=>$repo->grant($p),'upload'=>$repo->upload($key,$p),'fields'=>array_key_exists('submit_for_review',$p)?($p['submit_for_review']===true?(new CustomerPhotoSelection())->submit($key,$p['expected_head'],$p['expected_selection_revision']):throw new \InvalidArgumentException()): (array_key_exists('image_order',$p)?$repo->reorderImages($key,$p['expected_head'],$p['image_order']):$repo->saveFields($key,$p['expected_head'],$p['fields'])),'approve'=>$repo->approve($key,$p['version_sha256'],$p['context_sha256']),'revoke'=>$repo->revoke($key,$p['access_sha256']),'intake'=>isset($p['operation'])?$this->photoIntake($key,$p):$repo->operatorIntake($key,$p['version_sha256'],$p['image_field'],$p['rights'],$p['cutout_key']),'publish'=>isset($p['operation'])?$this->photoOperation($key,$p):$repo->publish($key,$p),'mockup'=>(new CustomerProductMockup())->approveEvidence($p['reference'],$p['sha256']),default=>throw new \InvalidArgumentException()};}
   if($result instanceof WP_Error)return $result;$response=new \WP_REST_Response($result);$response->header('Cache-Control','private, no-store');return $response;
  }catch(\Throwable){return new WP_Error('customer_editor_typed_request','Exact typed input is required.',['status'=>400]);}
 }
 private function photoIntake(string $key,array $p):array|WP_Error {
  if(($p['shop_key']??null)!=='personalized_pod')throw new \InvalidArgumentException();
  return match($p['operation']){'PHOTO_VIEW'=>(new CustomerPhotoSelection())->operatorView($key),'PHOTO_INPUT_REVIEW'=>(new CustomerPhotoSelection())->review($key,$p['selection_sha256'],$p['expected_revision'],$p['decision'],$p['note']),default=>throw new \InvalidArgumentException()};
 }
 private function photoOperation(string $key,array $p):array|WP_Error {
  $fields=in_array($p['operation']??'', ['PHOTO_PREPARE','PHOTO_LAYOUT'],true)?array_merge(['operation','shop_key','selection_sha256','expected_revision','template_key','template_version'],($p['operation']==='PHOTO_LAYOUT'?['note']:[])):['operation','shop_key','selection_sha256','expected_revision','note'];
  if(($p['shop_key']??null)!=='personalized_pod'||count($p)!==count($fields)||array_diff(array_keys($p),$fields))throw new \InvalidArgumentException();
  return match($p['operation']){'PHOTO_LAYOUT'=>(new CustomerPhotoSelection())->approvePhotoLayout($key,$p['selection_sha256'],$p['expected_revision'],$p['template_key'],$p['template_version'],$p['note']),'PHOTO_PREPARE'=>(new CustomerPhotoSelection())->prepare($key,$p['selection_sha256'],$p['expected_revision'],$p['template_key'],$p['template_version']),'PHOTO_APPROVE_RENDER'=>(new CustomerPhotoSelection())->approveRender($key,$p['selection_sha256'],$p['expected_revision'],$p['note']),default=>throw new \InvalidArgumentException()};
 }
 public function shortcode(array|string $attributes=[]):string {
  $a=shortcode_atts(['session'=>''],is_array($attributes)?$attributes:[]);$key=$a['session'];if($key==='')$key=isset($_GET['df_editor'])&&is_string($_GET['df_editor'])?wp_unslash($_GET['df_editor']):'';
  if(!is_string($key)||!preg_match('/^[A-Za-z0-9_-]{1,80}$/D',$key))return '<p>A personal order link is required.</p>';
  if(!is_user_logged_in())return '<p>Please <a href="'.esc_url(wp_login_url()).'">sign in</a> with your authorized order account.</p>';
  if(current_user_can('manage_digiforge_pod')&&\DigiForge\Security\ShopAccess::authorize('personalized_pod','manage_digiforge_pod')===true){$access=(new CustomerEditorRepository())->access($key,true);if($access instanceof WP_Error)return '<p>This order link is unavailable for your account.</p>';if((int)$access['customer_user_id']!==get_current_user_id()){wp_enqueue_style('digiforge-customer-editor',DIGIFORGE_URL.'assets/customer-editor.css',[],DIGIFORGE_VERSION);wp_enqueue_script('digiforge-customer-editor',DIGIFORGE_URL.'assets/customer-editor.js',[],DIGIFORGE_VERSION.'.'.substr(hash_file('sha256',DIGIFORGE_PATH.'assets/customer-editor.js'),0,12),true);return '<section class="df-editor" data-df-photo-review data-endpoint="'.esc_url(rest_url('digiforge/v1/customer-editor/'.rawurlencode($key).'/')).'" data-nonce="'.esc_attr(wp_create_nonce('wp_rest')).'">'.self::photoReviewMarkup().'</section>';}}
  $access=(new CustomerEditorRepository())->access($key);if($access instanceof WP_Error)return '<p>This order link is unavailable for your account.</p>';
  wp_enqueue_style('digiforge-customer-editor',DIGIFORGE_URL.'assets/customer-editor.css',[],DIGIFORGE_VERSION);
  wp_enqueue_script('digiforge-customer-editor',DIGIFORGE_URL.'assets/customer-editor.js',[],DIGIFORGE_VERSION.'.'.substr(hash_file('sha256',DIGIFORGE_PATH.'assets/customer-editor.js'),0,12),true);
  return '<section class="df-editor" data-df-editor data-endpoint="'.esc_url(rest_url('digiforge/v1/customer-editor/'.rawurlencode($key).'/')).'" data-nonce="'.esc_attr(wp_create_nonce('wp_rest')).'" aria-label="Personalize your artwork">'.self::markup().'</section>';
 }
 public static function markup():string {
  return <<<'HTML'
<h2>Personalize your artwork</h2><p>Local artwork review only. Your preference does not certify artwork or authorize production.</p>
<p data-status role="status" aria-live="polite">Loading your order…</p>
<form data-form><fieldset><legend>Your personalization</legend><div data-fields></div><label>Image field <select data-slot></select></label></fieldset>
<fieldset><legend>Photo preparation</legend><label><input type="radio" name="method" value="PHOTO"> Crop an ordinary photo (no background removal)</label><label><input type="radio" name="method" value="MANUAL" checked> Upload an already-cropped transparent PNG</label><label><input type="radio" name="method" value="AUTO"> Experimental offline background removal</label><p>PNG or JPEG; at most 4.5 MB and 1,048,576 pixels. Automatic extraction requires a selected head region and may need manual correction.</p><label>Photo <input data-file type="file" accept="image/png,image/jpeg"></label>
<div data-selection hidden><p>Select an interior rectangle around the head, then choose a foreground point inside it. Keep hair and ears within the rectangle. For ordinary photos, choose the crop rectangle only; no foreground point is used. Numeric controls also support keyboard selection.</p><canvas data-source aria-label="Source photo for head selection"></canvas><div class="df-coordinates"><label>Left <input data-coordinate="x" type="number" min="0"></label><label>Top <input data-coordinate="y" type="number" min="0"></label><label>Width <input data-coordinate="width" type="number" min="1"></label><label>Height <input data-coordinate="height" type="number" min="1"></label><label>Foreground X <input data-coordinate="px" type="number" min="1"></label><label>Foreground Y <input data-coordinate="py" type="number" min="1"></label></div></div>
<label><input data-rights type="checkbox"> I declare I have permission to submit and locally review this image.</label><label><input data-consent type="checkbox"> I consent to local image processing for this order.</label><p>These declarations do not establish verified licensing or commercial certification.</p><button data-upload type="submit">Save new artwork version</button><button data-save-fields type="button">Save text changes</button><button data-submit-photos type="button">Submit current photos for operator review</button><p data-photo-selection role="status"></p></fieldset></form>
<section aria-label="Compare artwork"><h3>Original and processed artwork</h3><label>Cutout background <select data-background><option value="checker">Transparency checkerboard</option><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Zoom <input data-zoom type="range" min="100" max="300" value="100"></label><div class="df-comparison"><figure><figcaption>Original</figcaption><div class="df-image"><img data-original alt="Your original uploaded image" hidden></div></figure><figure><figcaption>Processed artwork — cropped photo or cutout; not certified</figcaption><div class="df-image checker" data-cutout-background><img data-cutout alt="Current transparent cutout" hidden></div></figure></div><p data-quality></p></section>
<section aria-label="Digital product preview"><h3>Digital product preview</h3><p>Separate from source inspection. Reviewed local artwork or independently mapped product previews do not guarantee physical print parity. This simulation is not a physical print guarantee.</p><p data-product-status></p><img data-product alt="Digital product mockup of the approved artwork" hidden><button data-refresh type="button">Refresh preview</button><button data-approve type="button" disabled>Approve this digital preview</button></section>
<section aria-label="Photo ordering"><h3>Photo positions</h3><p>Upload every image position before reordering. Moving a photo creates a new version and invalidates the previous preview.</p><ol data-image-order></ol></section>
<section aria-label="Artwork version history"><h3>Version history</h3><ol data-history></ol></section>
HTML;
 }
 public static function photoReviewMarkup():string {return <<<'HTML'
<h2>Review customer photo artwork</h2><p>Input approval, local artwork approval and buyer preference are separate. Production stays held.</p><p data-review-status role="status" aria-live="polite">Loading current photo inputs…</p><div data-review-photos></div>
<label>Review note <textarea data-review-note maxlength="2000" required></textarea></label><label><input type="checkbox" data-review-confirm> I reviewed these exact current photos and their arrangement.</label><button data-review-input type="button">Approve current inputs only</button><button data-reject-input type="button">Reject current inputs</button>
<label>Approved product template <select data-review-template></select></label><button data-photo-layout type="button">Approve contained-photo layout</button><button data-prepare-photo type="button">Prepare local artwork for review</button><p>Use an existing reviewed recipe, or explicitly approve a contained-photo layout for one to four photos inside retained reviewed safe geometry. Missing geometry, seam conflicts or unsupported text placement block preparation.</p><img data-review-art alt="Current unapproved local photo artwork" hidden style="max-width:100%"><label><input type="checkbox" data-render-confirm> I inspected this exact rendered artifact. Preview and final local artwork must have identical bytes.</label><button data-approve-photo-render type="button">Approve this local artwork only</button><button data-photo-review-refresh type="button">Refresh current evidence</button><p>Customer opens the same order link to review the approved local preview. No provider or physical print certification.</p>
HTML;
 }

}
